pairs.verify_script:
package main

import (
	"fmt"
	"regexp"
)

var gitHubAlertRe = regexp.MustCompile(`(?i)^<p>\[!(NOTE|TIP|WARNING|IMPORTANT|CAUTION)\]`)

func main() {
	cases := []struct{ in string; want bool }{
		{`<p>[!NOTE]`, true},
		{`<p>[!note]`, true},
		{`<p>[!Tip]`, true},
		{`<p>[!warning]`, true},
		{`<p>[!X]`, false},
	}
	ok := true
	for _, c := range cases {
		if gitHubAlertRe.MatchString(c.in) != c.want {
			ok = false
		}
	}
	if ok {
		fmt.Println("All tests passed!")
	} else {
		fmt.Println("Some tests failed!")
	}
}
